import os
import subprocess
import zipfile
import xml.etree.ElementTree as ET

def get_pdf_text(path):
    try:
        return subprocess.check_output(['pdftotext', path, '-'], stderr=subprocess.DEVNULL).decode('utf-8', errors='ignore')
    except:
        return ""

def get_docx_text(path):
    try:
        with zipfile.ZipFile(path) as z:
            content = z.read('word/document.xml')
            root = ET.fromstring(content)
            return " ".join(node.text for node in root.iter() if node.text)
    except:
        return ""

def get_pptx_text(path):
    try:
        text = []
        with zipfile.ZipFile(path) as z:
            for f in z.namelist():
                if f.startswith('ppt/slides/slide'):
                    content = z.read(f)
                    root = ET.fromstring(content)
                    text.append(" ".join(node.text for node in root.iter() if node.text))
        return " ".join(text)
    except:
        return ""

def classify(text, filename):
    text = text.lower() + " " + filename.lower()
    if any(k in text for k in ['large language model', 'llm', 'transformer', 'gpt', 'pre-training', 'attention mechanism', 'neural machine translation']):
        return "LLM"
    if any(k in text for k in ['trapped ion', 'quantum computing', 'qubit', 'quantum gate', 'rydberg', 'ion trap', 'quantum simulation']):
        return "trapped_ion_and_qc"
    if any(k in text for k in ['black hole', 'event horizon', 'hawking radiation', 'general relativity', 'schwarzschild', 'gravitational wave']):
        return "black_hole"
    if any(k in text for k in ['dna', 'genome', 'nucleotide', 'genetics', 'sequencing', 'biological', 'chromosome', 'rna']):
        return "DNA"
    return "music_history"

source_dir = 'papers/all'
for filename in os.listdir(source_dir):
    path = os.path.join(source_dir, filename)
    if os.path.isdir(path): continue

    text = ""
    if filename.endswith('.pdf'):
        text = get_pdf_text(path)
    elif filename.endswith('.docx'):
        text = get_docx_text(path)
    elif filename.endswith('.pptx'):
        text = get_pptx_text(path)

    category = classify(text, filename)
    os.rename(path, os.path.join(category, filename))
